#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Room: perbaikan bingkai + fitur COMBO gift
#  1. Chat tidak lagi menimpa pesan sambutan/kursi (RecyclerView sekarang memotong isinya sendiri)
#  2. Bingkai SVGA di kursi dipotong di kotak 90dp supaya animasinya tidak meluber ke header;
#     jarak kursi dari header 34dp -> 40dp
#  3. COMBO: setelah hadiah terkirim muncul tombol bulat "COMBO xN" di kanan bawah dengan cincin
#     hitung mundur 4 detik. Ketuk lagi = kirim hadiah yang sama ke penerima yang sama
#     (tiap ketukan mengulang hitung mundur; berhenti kalau koin habis atau waktu habis).
# Menimpa: RoomActivity.kt dan GiftSheet.kt (backup otomatis). Layout diubah dengan sed.
# Jalankan di root repo:  bash pasang-room-combo.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
L="app/src/main/res/layout/activity_room.xml"
for f in "$D/GiftSheet.kt" "$D/RoomActivity.kt" "$L"; do
  [ -f "$f" ] || { echo "❌ $f tidak ditemukan. Jalankan di root repo Hayu-android"; exit 1; }
done
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"

BK="$HOME/.hayu-backup-roomcombo-$(date +%H%M%S)"
for f in "$D/GiftSheet.kt" "$D/RoomActivity.kt" "$L"; do
  mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"
done

for f in GiftSheet.kt RoomActivity.kt; do
  cp "$T/new/$D/$f" "$D/$f"
  echo "  dipasang   $D/$f"
done
rm -rf "$T"

# --- layout: chat memotong isinya sendiri + kursi lebih turun ---
if grep -q 'android:clipToPadding="false" android:paddingTop="8dp" android:paddingBottom="8dp"' "$L"; then
  sed -i 's#android:clipToPadding="false" android:paddingTop="8dp" android:paddingBottom="8dp"#android:clipToPadding="true" android:paddingTop="8dp" android:paddingBottom="8dp"#' "$L"
  echo "  DIPERBAIKI $L (daftar chat dipotong di batasnya)"
else
  echo "  ok         $L (daftar chat)"
fi
if grep -q 'android:paddingTop="34dp" android:paddingBottom="10dp"' "$L"; then
  sed -i 's#android:paddingTop="34dp" android:paddingBottom="10dp"#android:paddingTop="40dp" android:paddingBottom="10dp"#' "$L"
  echo "  DIPERBAIKI $L (jarak kursi 40dp)"
else
  echo "  ok         $L (jarak kursi)"
fi

echo ""
echo "✅ Selesai. Backup: $BK"
echo "   (RoomActivity.kt & GiftSheet.kt ditimpa dengan versi repo _4 + perbaikan; kalau kamu mengubahnya setelah itu, ambil dari backup)"
echo "Lanjut: git add -A && git commit -m 'room: bingkai tidak nabrak + combo gift' && git push"
